import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc = inputs["cdc_events"].copy()

    # 1. Deduplicate events by seq (at-least-once delivery -> apply once).
    cdc = cdc.drop_duplicates(subset=["seq"], keep="first")

    # Build initial target map: order_id -> {status, amount, last_seq}
    target_map = {}
    for _, row in target_state.iterrows():
        target_map[int(row["order_id"])] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": int(row["last_seq"]),
        }

    new_map = dict(target_map)  # will be mutated into the final state
    tombstones = []

    orders_with_events = cdc["order_id"].unique()

    for order_id_raw in orders_with_events:
        order_id = int(order_id_raw)
        group = cdc[cdc["order_id"] == order_id_raw].sort_values("seq")

        has_target = order_id in target_map
        last_seq_target = target_map[order_id]["last_seq"] if has_target else None

        # 2. Replay guard: skip events with seq <= existing target last_seq.
        if has_target:
            group = group[group["seq"] > last_seq_target]

        if group.empty:
            continue  # nothing to apply for this order; carried forward unchanged

        current = dict(target_map[order_id]) if has_target else None
        had_row_ever = has_target
        last_op = None
        last_seq_applied = None

        # 3. Apply remaining events in seq order.
        for _, ev in group.iterrows():
            op = ev["op"]
            seq = int(ev["seq"])

            if op in ("I", "U"):
                if current is None:
                    # Fresh creation: take event amount as-is (NULL stays NULL).
                    amount = ev["amount"]
                    status = ev["status"]
                else:
                    status = ev["status"]
                    if op == "U" and pd.isna(ev["amount"]):
                        amount = current["amount"]
                    else:
                        amount = ev["amount"]
                current = {"status": status, "amount": amount, "last_seq": seq}
                had_row_ever = True
                last_op = "U"
            elif op == "D":
                current = None
                last_op = "D"

            last_seq_applied = seq

        # 4. Update new_map with result of processing this order.
        if current is not None:
            new_map[order_id] = current
        else:
            if order_id in new_map:
                del new_map[order_id]

        # 5. Tombstone: order had a row at some point and last applied event is 'D'.
        if current is None and last_op == "D" and had_row_ever:
            tombstones.append({"order_id": order_id, "deleted_seq": last_seq_applied})

    # Build new_state DataFrame.
    new_state_rows = []
    for order_id, row in new_map.items():
        new_state_rows.append(
            {
                "order_id": order_id,
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"],
            }
        )

    new_state_df = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    if not new_state_df.empty:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")
        new_state_df["amount"] = new_state_df["amount"].astype("float64")
    else:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")
        new_state_df["amount"] = new_state_df["amount"].astype("float64")
        new_state_df["status"] = new_state_df["status"].astype("object")

    tombstones_df = pd.DataFrame(tombstones, columns=["order_id", "deleted_seq"])
    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")
    else:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")

    return {"new_state": new_state_df, "tombstones": tombstones_df}
